```typescript
interface User {
  id: number;
  name: string;
  orgId: number;
  org?: Org;
}

interface Org {
  id: number;
  name: string;
}

async function loadUser(id: number): Promise<User> {
  const res = await fetch(`/api/users/${id}`);
  if (!res.ok) {
    throw new Error(`bad status ${res.status}`);
  }
  const user: User = await res.json();

  const orgRes = await fetch(`/api/orgs/${user.orgId}`);
  if (!orgRes.ok) {
    throw new Error(`bad status ${orgRes.status}`);
  }
  user.org = await orgRes.json();
  return user;
}

async function loadUsers(ids: number[]): Promise<User[]> {
  const results = await Promise.all(ids.map((id) => loadUser(id)));
  return results;
}

export { loadUser, loadUsers };
